-- aar/w3/aar_row_632_draft3.sql. DRAFT 3 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 632 (the input-token field of an OpenRouter cost entry is never negative) and its ask_aar_builders row.
-- Every value is from Wall 11931, 11986, 11988, 11989, 11990, 11993 and 11994 (11993 and 11994 read whole by W3; the others in their first 700 to 1,200 characters), ask632/w1/plan632.md rev 1 (read whole), ask632/w1/b1/notes632.md (read whole), ask632/w4/record632.md (read whole; the card, the audit id and the write facts are W4's), and md5sum by W3 of the files named.
-- NOT READ by W3: the card itself; audit_log row 42123; the live Panel Tokens code; n8n; W1's and W4's grade files in git.
-- objective_met is 'in part': written and read back; no run since the write.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (632, '0', $t$ASK 632: the input-token field of an OpenRouter cost entry is never negative, and is right when the cache write repeats the cache read$t$,
  $t$In call_costs the field i (input tokens not served from cache) was wrong for google/gemini-3.8-flash whenever OpenRouter reported a cache write: Panel Tokens computed i as prompt tokens minus cache read minus cache write, and for this model the write count repeats the read count, so i came out negative (57 stored entries in 24 runs, from -1 to -77,682). Change: in Panel Tokens' OpenRouter branch only, when the write is above 0 and equals the read, or the remainder is below 0, i is prompt tokens minus cache read, never below 0, and the entry carries ov:1. Expected effect: no new entry has i below 0, and the 57 stored cases would give the uncached input the billed cost implies (QR Ask 664, not -75,869). Not changed: cr and w5 as reported, the billed dollars, run_cost_usd and every token total. (plan rev 1, heading 1, ask632/w1/plan632.md md5 ad95ec73)$t$,
  'in part',
  $t$Written by W4 at 06:00 CST 2026-11-25 on the operator's press "Write it" on W4's card at 05:59 CST (Wall 11993; audit 42123 by W4's record file), engine 066525aa to 3b72583c, and read back PASS by W1 (Wall 11994: node-equal to the target d46b0b59, connections equal, only Panel Tokens differs from 066525aa, t632 20 of 20 on the live engine, standing set 31 PASS 0 FAIL). One statement in Panel Tokens changed; the child aad0ad9c is unchanged. IN PART, because no run has been made since the write: the objective is shown only by a run in which a gemini-3.8-flash call reports a cache write. Offline (W1's build b1, reproduced by W4, Wall 11990): the new statement on the 1,922 stored OpenRouter entries gives i = prompt minus read with ov 1 on the 57 negative entries and leaves the other 1,865 byte-equal; seven synthetic cases pass; the per-model sum of i is unchanged for 19 models and rises for gemini-3.8-flash from 29,593 to 1,818,652, the w5 sum of the 57. W1's fit (fit632.sql): the billed cost of all 111 stored gemini-3.8-flash entries is priced exactly only when the uncached input is prompt minus read. The 57 stored entries are left as written; correcting them is a separate question for the operator (plan heading 8). NOT SEARCHED by W1: the dashboard pages that may show i. Mistakes reported by the seats: W1's first C5 test used a wrong pattern and failed on a correct build (replaced; the build did not change); W4's write script stopped once before any write and did not find its own fetch-back after the write (fetched back by hand; nothing wrong was written). Seen in runs 42373 (one entry), 42517 (five) and 42528 (one). Open: two clean live runs.$t$,
  '11931, 11986, 11988, 11989, 11990, 11993, 11994',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo58DjKj6vJTSoL8pwo16XFy12, "Write ASK 632 so a gemini cost entry never shows negative input tokens?"): he pressed "Write it" at 05:59 CST 2026-11-25. The card is from W4's record file ask632/w4/record632.md (deda4257); W3 did not read it. There was no build card: the build was offline files only, and the card came after the build grade.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 632 so a gemini cost entry never shows negative input tokens?", "options": {"Write it": "I change one line in the engine's Panel Tokens node, fetch it back, and W1 reads it back. No dollar figure changes. Undo restores the 066525aa engine.", "Hold": "The engine stays as it is, and gemini-3.8-flash entries keep a negative or understated input-token count."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58DjKj6vJTSoL8pwo16XFy12", "press_time": "05:59 CST 2026-11-25", "source": "ask632/w4/record632.md (deda4257); Wall 11993. Card not read by W3."}$j$::jsonb,
  'W1',
  $j${"md5": "ad95ec733ffb84a6e07daf22bbd18337", "path": "ask632/w1/plan632.md", "note": "plan rev 1; rev 0 (df307821, commit a10b47b7) graded PASS WITH N1 to N3 by W4 (Wall 11988); rev 1 applies them by its own first line and is named in W4's build grade (Wall 11990).", "source": "md5sum by W3; Wall 11986, 11988, 11990"}$j$::jsonb,
  $j$[{"path": "ask632/w1/b1/b632.cjs", "md5": "2b9d009eee55f0cecc2b48b9fbff71cc", "what": "build script"}, {"path": "ask632/w1/b1/tg/target_engine_632.json", "md5": "d46b0b595573b4f61d8973f7b72bf318", "what": "target engine"}, {"path": "ask632/w1/b1/t632.cjs", "md5": "44dbc1adbedd7521a90540f97c9b24a6", "what": "test"}, {"path": "ask632/w1/b1/notes632.md", "md5": "4261a96df5262797ad75de5d9f225d87", "what": "build notes"}, {"path": "ask632/w1/fit632.sql", "md5": "62565c4bb15ac6289443f5de8d38bd11", "what": "price fit"}, {"path": "ask632/w4/write/write632.sh", "md5": "1b4c3d485ee0efdafa197702f48ec70e", "what": "write script"}, {"path": "ask632/w4/write/fetchback_eng_632.json", "md5": "9c0a1188f4e8e3f24656c2b02f3729ba", "what": "fetch-back after the write"}]$j$::jsonb,
  $j${"engine": "ask632/w4/write/revert_eng_632.json, md5 2aa215bc486b649b7fa879b5392b9d98 (restores 066525aa)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "ask632/w4/record632.md; Wall 11993; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W4", "verdict": "PASS WITH N1 to N3 (plan rev 0)", "wall_id": 11988, "md5_graded": "df307821", "verdict_norm": "PASS", "source": "Wall 11988"}, {"seat": "W4", "verdict": "PASS (build b1)", "wall_id": 11990, "md5_graded": "d46b0b595573b4f61d8973f7b72bf318", "verdict_norm": "PASS", "source": "Wall 11990"}]$j$::jsonb,
  ARRAY['d46b0b595573b4f61d8973f7b72bf318'], '[42123]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, node Panel Tokens", "before": "version 066525aa; e.i=__N(u.prompt_tokens)-e.cr-e.w5", "after": "version 3b72583c; when (w5>0 and w5 equals cr) or the remainder is below 0: ov=1 and i=max(0, prompt-cr); otherwise as before (ask632/w1/b1/notes632.md). 423 nodes, connections equal."}]$j$::jsonb,
  $j$[{"name": "t632.cjs on the build", "result": "ALL PASS (20): C1 57 negative entries fixed with ov 1; C2 1,865 other entries byte-equal; C3 seven synthetic cases; C4 structure; C5 only the tagged statement differs; C6 19 models unchanged, gemini-3.8-flash i sum 29,593 to 1,818,652", "source": "ask632/w1/b1/notes632.md; Wall 11989; reproduced by W4, Wall 11990"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W1, W4) and on the fetch-back (W4, Wall 11993) and on live (W1, Wall 11994)", "source": "Wall 11989, 11990, 11993, 11994"}, {"name": "NOT RUN", "result": "any live call; the plan needs none (stored usages are the test)", "source": "plan632.md heading 6"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (live 3b72583c, active, 423 nodes, node-equal to target d46b0b59, connections equal; only Panel Tokens differs from 066525aa; t632 20 of 20 on live; standing 31 PASS 0 FAIL)", "wall_id": 11994, "source": "Wall 11994 (commit 67e2681e)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "on the first run in which a gemini-3.8-flash call reports a cache write (recently: Accept calls, Synthesis, QR Ask, alternates): no call_costs entry has i below 0; the gemini-3.8-flash entries with w5 above 0 carry ov:1 and i equal to prompt minus read.", "not_shown": "the statement on a live reply.", "source": "plan632.md heading 6"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN by W3 on the operator's press \"Write it\" at 06:15 CST 2026-11-25: part 13.0, version 314 to version 323, md5 bbb1e3e40e1ca7b152795677bdcc39b0, 17,743 characters; one sub-bullet added, nothing removed (pair manual1123/w3/a632/em_pairs_632_draft1.json c6a7a763, W1 PASS Wall 11999; log row 343; audit 42145; Wall 12013). Read back PASS by W1 (Wall 12015)."}$j$::jsonb,
  'read back', $j$[11931, 11986, 11988, 11989, 11990, 11993, 11994]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W1'], $j$[{"seat": "W1", "what": "planned and built ASK 632 offline (build b1)", "wall_id": 11989}, {"seat": "W4", "what": "wrote the engine on the operator's card", "wall_id": 11993}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
